      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Reversing fatty liver disease</text>\n                    <rect x=\"100\" y=\"180\" width=\"900\" height=\"200\" rx=\"20\" fill=\"rgba(239,68,68,0.12)\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"235\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"26\">NAFLD CAUSE</text>\n                    <text x=\"550\" y=\"285\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Fructose → de novo lipogenesis</text>\n                    <text x=\"550\" y=\"325\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Liver makes fat from sugar</text>\n                    <text x=\"550\" y=\"365\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">No fat in the diet required</text>\n                    <rect x=\"100\" y=\"420\" width=\"900\" height=\"200\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"475\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"26\">THE FIX</text>\n                    <text x=\"550\" y=\"525\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Cut added sugar drastically</text>\n                    <text x=\"550\" y=\"565\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Especially liquid sugar</text>\n                    <text x=\"550\" y=\"600\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Liver heals in weeks, not years</text>\n                    <rect x=\"200\" y=\"680\" width=\"700\" height=\"160\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"730\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">Treat the root cause —</text>\n                    <text x=\"550\" y=\"765\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">not the symptoms.</text>\n                    <text x=\"550\" y=\"800\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">Sugar in → liver fat out.</text>\n                </svg>",
      "caption": "The lever is sugar — pull it"
